+++ b/src/test/java/com/harborledger/billing/InvoiceDueDateCalculatorTest.java
@@ -19,14 +19,24 @@ class InvoiceDueDateCalculatorTest {

         assertEquals(Instant.parse("2026-03-04T05:00:00Z"), dueAt);
     }

     @Test
+    void paymentTermKeepsLocalMidnightAcrossDaylightSavingChange() {
+        Instant dueAt = calculator.dueAt(
+                LocalDate.of(2026, 2, 14),
+                30,
+                BillingTestFixture.newYorkBillingZone());
+
+        assertEquals(Instant.parse("2026-03-16T04:00:00Z"), dueAt);
+    }
+
+    @Test
     void rejectsNegativePaymentTerms() {
         assertThrows(
                 IllegalArgumentException.class,
                 () -> calculator.dueAt(
                         LocalDate.of(2026, 2, 2),
                         -1,
                         BillingTestFixture.newYorkBillingZone()));
     }
 }
